<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor\UserProfileGenderAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileGenderAccessor trait.
 *
 * Covers null default, string/VO assignment via withGender,
 * getGender/gender accessors, and isGenderChanged with/without original.
 */
class UserProfileGenderAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withGender creates a new instance with the Gender set
     * from a string value, and getGender returns the primitive string.
     */
    public function testWithGenderFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileGenderAccessorUnitTest();

        // Act
        $result = $holder->withGender('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getGender());
    }
    /**
     * Asserts that withgender has access to the value object
     * from a string value, and getGender returns the primitive string.
     */
    public function testWithGenderFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileGenderAccessorUnitTest();

        // Act
        $result = $holder->withGender('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->gender()->value());
    }
    public function testChangedGender(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileGenderAccessorUnitTest();
        $original = $holder->withGender('one');
        $same = $holder->withGender('one');
        $modified = $holder->withGender('other');

        // Act
        $unchanged = $holder->isGenderChanged();
        $withSame = $original->isGenderChanged($same);
        $withDiferent = $original->isGenderChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserProfileGenderAccessorUnitTest
{
    use UserProfileGenderAccessor;
}
